# Load R resources
library(traits.build)

# Load data resources
schema <- get_schema()
resource_metadata <- get_schema("config/metadata.yml", "metadata")
definitions <- get_schema("config/traits.yml", "traits")
unit_conversions <- get_unit_conversions("config/unit_conversions.csv")
taxon_list <- read_csv_char("config/taxon_list.csv")

# Build each source
Both_2019_config <- dataset_configure("data/Both_2019/metadata.yml", definitions)
Both_2019_raw <- dataset_process("data/Both_2019/data.csv", Both_2019_config, schema, resource_metadata, unit_conversions)
Both_2019 <- dataset_update_taxonomy(Both_2019_raw, taxon_list)


MYtraits_raw <- austraits::bind_databases(
  Both_2019,
  NULL)

# Version information
version_number <- util_get_version("config/metadata.yml")
git_SHA <- util_get_SHA()

# Combine all the source into one resource
MYtraits <- build_add_version(MYtraits_raw, version_number, git_SHA)

# Save to file
dir.create("export/data/curr", FALSE, TRUE)
saveRDS(MYtraits, "export/data/curr/MYtraits.rds")
